let puppeteer = require("rebrowser-puppeteer-core");
const { pageController } = require("./module/pageController.js");
const {
  isTermux,
  getTermuxChromePath,
  mergeTermuxFlags,
  launchWithXvfbRun,
} = require("./module/termux.js");

let Xvfb;
try {
  Xvfb = require("xvfb");
} catch {
  // ignore — not available in all environments (e.g. Termux)
}

async function connect({
  args = [],
  headless = false,
  customConfig = {},
  proxy = {},
  turnstile = false,
  connectOption = {},
  disableXvfb = false,
  plugins = [],
  ignoreAllFlags = false,
} = {}) {
  const { launch, Launcher } = await import("chrome-launcher");

  let xvfbsession = null;
  if (headless == "auto") headless = false;

  const termux = isTermux();

  // Auto-detect Chromium path on Termux if not explicitly provided
  if (termux && !customConfig.chromePath) {
    const termuxChrome = getTermuxChromePath();
    if (termuxChrome) {
      customConfig = { ...customConfig, chromePath: termuxChrome };
    } else {
      console.warn(
        "[puppeteer-termux] Running on Termux but no Chromium binary found.\n" +
        "Install it with: pkg install chromium"
      );
    }
  }

  let chromeFlags;
  if (ignoreAllFlags === true) {
    chromeFlags = [
      ...args,
      ...(headless !== false ? [`--headless=${headless}`] : []),
      ...(proxy && proxy.host && proxy.port
        ? [`--proxy-server=${proxy.host}:${proxy.port}`]
        : []),
    ];
  } else {
    // Default flags: https://github.com/GoogleChrome/chrome-launcher/blob/main/src/flags.ts
    const flags = Launcher.defaultFlags();
    // Add AutomationControlled to "disable-features" flag
    const indexDisableFeatures = flags.findIndex((flag) => flag.startsWith('--disable-features'));
    flags[indexDisableFeatures] = `${flags[indexDisableFeatures]},AutomationControlled`;
    // Remove "disable-component-update" flag
    const indexComponentUpdateFlag = flags.findIndex((flag) => flag.startsWith('--disable-component-update'));
    flags.splice(indexComponentUpdateFlag, 1);
    chromeFlags = [
      ...flags,
      ...args,
      ...(headless !== false ? [`--headless=${headless}`] : []),
      ...(proxy && proxy.host && proxy.port
        ? [`--proxy-server=${proxy.host}:${proxy.port}`]
        : []),
      "--no-sandbox",
      "--disable-dev-shm-usage",
    ];
  }

  // On Termux, always inject essential flags even when ignoreAllFlags=true
  if (termux) {
    chromeFlags = mergeTermuxFlags(chromeFlags);
  }

  let chrome;

  if (termux && !headless && !disableXvfb) {
    // Termux + headful: xvfb npm package is incompatible — use xvfb-run as a process wrapper
    const chromePath = customConfig.chromePath;
    if (!chromePath) {
      throw new Error(
        "[puppeteer-termux] Cannot launch headful browser on Termux: no Chromium path found.\n" +
        "Install Chromium with: pkg install chromium\n" +
        "Install xvfb-run with:  pkg install xorg-server-xvfb"
      );
    }
    console.log("[puppeteer-termux] Termux detected — launching Chromium via xvfb-run");
    chrome = await launchWithXvfbRun(chromePath, chromeFlags);
  } else if (termux && headless) {
    // Termux + headless: use chrome-launcher with auto-detected path, no Xvfb needed
    chrome = await launch({
      ignoreDefaultFlags: true,
      chromeFlags,
      ...customConfig,
    });
  } else {
    // Standard Linux / non-Termux: use Xvfb npm package
    if (process.platform === "linux" && disableXvfb === false && !headless) {
      try {
        xvfbsession = new Xvfb({
          silent: true,
          xvfb_args: ["-screen", "0", "1920x1080x24", "-ac"],
        });
        xvfbsession.startSync();
      } catch (err) {
        console.log(
          "You are running on a Linux platform but do not have xvfb installed. The browser can be captured.\n" +
          "Install it with: sudo apt-get install xvfb\n\n" +
          err.message
        );
      }
    }

    chrome = await launch({
      ignoreDefaultFlags: true,
      chromeFlags,
      ...customConfig,
    });
  }

  if (plugins.length > 0) {
    const { addExtra } = await import("puppeteer-extra");
    puppeteer = addExtra(puppeteer);
    for (const item of plugins) {
      puppeteer.use(item);
    }
  }

  const browser = await puppeteer.connect({
    browserURL: `http://127.0.0.1:${chrome.port}`,
    ...connectOption,
  });

  let [page] = await browser.pages();

  let pageControllerConfig = {
    browser,
    page,
    proxy,
    turnstile,
    xvfbsession,
    pid: chrome.pid,
    plugins,
  };

  page = await pageController({
    ...pageControllerConfig,
    killProcess: true,
    chrome,
  });

  browser.on("targetcreated", async (target) => {
    if (target.type() === "page") {
      let newPage = await target.page();
      pageControllerConfig.page = newPage;
      newPage = await pageController(pageControllerConfig);
    }
  });

  return {
    browser,
    page,
  };
}

module.exports = { connect, isTermux, getTermuxChromePath };
